srcDoc.css:
body {
  margin: 0;
  background: #f3f4f6;
  color: #111827;
  font-family: Arial, sans-serif;
}

.print-button {
  display: block;
  margin: 10px auto;
  padding: 8px 14px;
  border: 0;
  background: #111827;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.slip {
  width: 80mm;
  margin: 0 auto;
  padding: 5mm;
  box-sizing: border-box;
  background: white;
  font-size: 12px;
  line-height: 1.35;
}

.top {
  text-align: center;
}

.brand {
  font-size: 17px;
  font-weight: 900;
  text-transform: uppercase;
}

.title {
  margin-top: 4px;
  font-size: 14px;
  font-weight: 900;
  text-transform: uppercase;
}

.small {
  color: #4b5563;
  font-size: 10px;
}

.divider {
  border-top: 1px dashed #111827;
  margin: 9px 0;
}

.section-title {
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.line {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 4px 0;
}

.line span {
  color: #4b5563;
}

.line strong {
  text-align: right;
}

.grand {
  padding: 8px 0;
  border-top: 2px solid #111827;
  border-bottom: 2px solid #111827;
  font-size: 15px;
  font-weight: 900;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  text-align: left;
  color: #4b5563;
  font-size: 10px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e5e7eb;
}

td {
  padding: 5px 0;
  vertical-align: top;
  border-bottom: 1px solid #f3f4f6;
}

.num {
  text-align: right;
  white-space: nowrap;
}

.note {
  white-space: pre-wrap;
  color: #374151;
}

.qr-box {
  text-align: center;
}

.qr {
  width: 104px;
  height: 104px;
  image-rendering: pixelated;
}

.signature {
  font-size: 10px;
}

.signature-line {
  height: 22px;
  border-bottom: 1px solid #111827;
  margin-bottom: 8px;
}

.footer {
  text-align: center;
  font-size: 10px;
}

.footer strong,
.footer span {
  display: block;
}

@media print {
  body {
    background: white;
  }
  .print-button {
    display: none;
  }
  .slip {
    margin: 0;
    padding: 4mm;
  }
}

srcDoc.js:
function val(value) {
  return String(value ?? "");
}
function money(value) {
  return Number(value || 0).toFixed(2);
}
function titleByType(type) {
  const map = {
    OPENING: "Opening Cash",
    CASH_IN: "Cash In",
    CASH_OUT: "Cash Out",
    CLOSING: "Closing Cash"
  };
  return map[type] || "Cash Slip";
}
function qrPayload(model) {
  return ["TYPE=" + val(model.type), "REF=" + val(model.referenceNumber), "REGISTER=" + val(model.cashRegister), "DATE=" + val(model.transactionDate), "AMOUNT=" + money(model.amount)].join("&");
}
function qrSrc(payload) {
  return "https://api.qrserver.com/v1/create-qr-code/?size=120x120&ecc=M&margin=1&data=" + encodeURIComponent(payload);
}
function render(model) {
  model = model || {};
  const lines = model.lines || [];
  document.getElementById("title").innerText = model.title || titleByType(model.type);
  document.getElementById("cashRegister").innerText = val(model.cashRegister || "");
  document.getElementById("reference").innerText = "Reference: " + val(model.referenceNumber || "-");
  document.getElementById("transactionDate").innerText = val(model.transactionDate || "");
  document.getElementById("amount").innerText = money(model.amount) + " EUR";
  document.getElementById("linesBody").innerHTML = lines.length ? lines.map(row => `
      <tr>
        <td>${money(row.denominationValue)}</td>
        <td class="num">${val(row.quantity)}</td>
        <td class="num">${money(row.amount)}</td>
      </tr>
    `).join("") : `<tr><td colspan="3">No cash breakdown</td></tr>`;
  if (model.note) {
    document.getElementById("noteSection").style.display = "block";
    document.getElementById("note").innerText = model.note;
  } else {
    document.getElementById("noteSection").style.display = "none";
  }
  const payload = qrPayload(model);
  document.getElementById("qr").src = qrSrc(payload);
  document.getElementById("qrText").innerText = val(model.referenceNumber || "");
  document.getElementById("printedBy").innerText = model.printedBy ? "Printed by: " + val(model.printedBy) : "";
  document.getElementById("printedAt").innerText = model.printedAt ? "Printed at: " + val(model.printedAt) : "";
  document.getElementById("printBtn").onclick = () => window.print();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

